import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"版本管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/versioning.md","filePath":"zh/release/versioning.md"}'),r={name:"zh/release/versioning.md"};function c(i,e,l,s,n,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h1><h2 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h2><p>自 v1.0.0 公开发布起，版本标识符是 <strong>SemVer</strong>： <code>1.0.0</code>、<code>2.0.0</code>、<code>2.1.0</code>……在那之前，工程阶段使用工作包 阶段名（<code>WP-14-docs_release</code>、<code>WP-13-build_system</code>、 ……）——相当于按特性集开行的内部发布列车。自 v2.0.0 起， tag 是纯粹的 <code>v&lt;version&gt;</code>（<code>git tag v2.1.0</code>），<code>WP-*</code> tag 只 存在于历史中。</p><p>此外，每个构建携带：</p><ul><li><strong>构建号</strong> = 构建时的提交计数（<code>git rev-list --count HEAD</code>） <strong>加上永久的 +21 对齐偏移</strong>（Makefile 中的 <code>OC_KERNEL_BUILD_OFFSET := 21</code>）。该偏移始于 v1.0.0：已 公布的构建号烘焙自一棵 git 历史比公开仓库 main 长 21 个 提交的工程树（WP-14-docs_release 以公开计数 253 发布了 构建 274），而 OTA 更新检查按<strong>数值</strong>比较构建号 （BUG-0347）——所以公开序列必须接续在已发布的 274 之上。 一提交一构建的单调性得以保持：v1.0.0 tag 位于公开计数 257 -&gt; 构建 278；v2.0.0 位于计数 281 -&gt; 构建 302。</li><li><strong>版本横幅</strong> = Makefile 中冻结的 <code>OC_RELEASE_VERSION ?=</code> 字面量（显式 <code>OC_RELEASE_VERSION=</code> 覆盖仍然优先——E2E 更新测试正是靠它工作的）——烘焙进内核横幅、uname、OTA 清单和 ISO。更早的构建从 <code>git describe --tags</code> 推导它； v1.0.0 把它冻结为字面量，横幅从此不再依赖本地 git 状态。</li></ul><h2 id="数字合在一起的意义" tabindex="-1">数字合在一起的意义 <a class="header-anchor" href="#数字合在一起的意义" aria-label="Permalink to &quot;数字合在一起的意义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS 2.1.0 x86_64</code></td><td>运行中内核的版本</td></tr><tr><td>update.json</td><td><code>version: 2.1.0, build: &lt;n&gt;</code></td><td>已发布的清单</td></tr><tr><td>Release tag</td><td><code>v2.1.0</code></td><td>资产构建所用的 git tag</td></tr><tr><td>gh-pages</td><td>下载页上的同样两个数字</td><td>网站镜像 Release</td></tr></tbody></table><p>一次发布 = 一个 tag = 一个构建号 = 一份清单 = 一组 SHA256，横跨本地 / Release / gh-pages / 私有镜像。tag 必须 指向 CI 绿的提交（2.1.0 发布门禁）。</p><h2 id="兼容性承诺" tabindex="-1">兼容性承诺 <a class="header-anchor" href="#兼容性承诺" aria-label="Permalink to &quot;兼容性承诺&quot;">​</a></h2><ul><li>Shell 命令绝不无声移除，删除必须在删除登记表中声明；新增 才是常态。v1.0.0 的 233 条命令基线完整保留：每一条都映射 在 <code>INTERFACES.md</code> Part 1c 兼容性契约中（251 个 v2 命令 归属 = 99 L0 + 133 SVC + 19 内建）。</li><li>L1SVC 操作号绝不重排；新操作只追加（2.1.0 时为 17 个类别 / 158 个操作）。退役的 v1 编号面的下场逐条 记录：<code>INTERFACES.md</code> Part 2c/2d。</li><li>OTA 包只更新内核；/etc 卷内容向前延续。</li><li>从此遵循 SemVer：破坏性变更升 MAJOR，新命令或新 L1SVC 操作升 MINOR，修复升 PATCH。</li></ul><h2 id="选择下一个版本号" tabindex="-1">选择下一个版本号 <a class="header-anchor" href="#选择下一个版本号" aria-label="Permalink to &quot;选择下一个版本号&quot;">​</a></h2><p>按上面的 SemVer 规则；<code>build</code> = 发布日的提交计数 + 21—— 从不手挑。</p><h2 id="版本号纪律-交叉引用" tabindex="-1">版本号纪律（交叉引用） <a class="header-anchor" href="#版本号纪律-交叉引用" aria-label="Permalink to &quot;版本号纪律（交叉引用）&quot;">​</a></h2><p>3.0.0 阶段的约束性规则见 <a href="./../root/CONTRIBUTING.html#版本号纪律300-阶段">CONTRIBUTING.md</a>：74 个工作包 走完之前版本主干固定为 <code>3.0.0-WP-&lt;工作包名&gt;</code>，<code>OC_RELEASE_VERSION</code> 是唯一 真源，版本变更属全仓对账并以 <code>git grep</code> 验证，绝不只是一处文件的修改。</p><h2 id="提交与推送纪律-交叉引用" tabindex="-1">提交与推送纪律（交叉引用） <a class="header-anchor" href="#提交与推送纪律-交叉引用" aria-label="Permalink to &quot;提交与推送纪律（交叉引用）&quot;">​</a></h2><p><a href="./../root/CONTRIBUTING.html#提交与推送纪律">批量交付规则</a>：一次验证过的 批量 → 一次推送，同时覆盖公开仓与私密镜像仓，推送后线上验证 gh-pages。</p>',16)])])}const u=t(r,[["render",c]]);export{_ as __pageData,u as default};
